import{_ as n,C as r,o as s,c as i,aj as e,E as o}from"./framework.js";const b=JSON.parse('{"title":"Integrations | Settings / Integrations | Admin CMS","description":"Integrations centralizes site CoreSetting: database, payment, SMS, OAuth login, object storage, JWT, etc. The page groups items by Group; each row shows name and value summary…","frontmatter":{"title":"Integrations | Settings / Integrations | Admin CMS","description":"Integrations centralizes site CoreSetting: database, payment, SMS, OAuth login, object storage, JWT, etc. The page groups items by Group; each row shows name and value summary…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/settings/integrations/index.html"}]]},"headers":[],"relativePath":"cms/settings/integrations/index.md","filePath":"en/cms/settings/integrations/index.md","lastUpdated":1781010536000}'),d={name:"cms/settings/integrations/index.md"};function l(c,t,g,h,p,m){const a=r("DocImage");return s(),i("div",null,[t[0]||(t[0]=e('<h1 id="integrations" tabindex="-1">Integrations <a class="header-anchor" href="#integrations" aria-label="Permalink to &quot;Integrations&quot;">​</a></h1><blockquote><p>Menu: <strong>Settings -&gt; Integrations</strong><br> Deep link: <code>/_Admin/system/config?SiteId={siteGuid}</code></p></blockquote><p><strong>Integrations</strong> centralizes site <strong>CoreSetting</strong>: database, payment, SMS, OAuth login, object storage, JWT, etc. The page groups items by <strong>Group</strong>; each row shows <strong>name</strong> and <strong>value summary</strong> (masked/truncated in the list). Click <strong>Edit</strong> to open the config dialog.</p><div class="tip custom-block"><p class="custom-block-title">Permissions</p><p>View list: <code>config</code>. Edit and save any item: <code>config·edit</code>.</p></div><div class="warning custom-block"><p class="custom-block-title">Security</p><p>Dialogs often contain <strong>secrets, connection strings, certificates</strong>, etc. Do not put real values in public docs or Git; CMS docs explain <strong>admin paths and field meaning</strong>—values come from vendor consoles.</p></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In <a href="./../../navigation.html#permissions-and-edit-menu">Edit Menu</a>, enable <strong>Settings -&gt; Integrations</strong>.</li><li>Open <strong>Settings -&gt; Integrations</strong> in the left sidebar.</li></ol><p>URL query <strong><code>group</code></strong> expands a group, e.g. <code>group=Database</code> from <a href="./../../database/mysql-table.html">MySQL tables</a> onboarding.</p>',8)),o(a,{src:"/cms/settings/settings-integrations-overview.png",alt:"Integrations overview",width:"1120"}),t[1]||(t[1]=e('<h2 id="page-structure" tabindex="-1">Page Structure <a class="header-anchor" href="#page-structure" aria-label="Permalink to &quot;Page Structure&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Description</th></tr></thead><tbody><tr><td><strong>Fold groups</strong></td><td>Group title (e.g. <code>Database</code>, <code>Payment</code>); multiple groups can be open</td></tr><tr><td><strong>Row: Name</strong></td><td>Integration <code>name</code>, matches scripts/admin API (e.g. <code>Mysql</code>, <code>Alipay</code>)</td></tr><tr><td><strong>Row: Value</strong></td><td><code>value</code> summary (often JSON or connection snippet), truncated when long</td></tr><tr><td><strong>Row: Edit</strong></td><td>Pencil; <code>data-cy</code> is item name; requires <code>config·edit</code></td></tr></tbody></table>',2)),o(a,{src:"/cms/settings/settings-integrations-database.png",alt:"Database group",width:"1120"}),t[2]||(t[2]=e('<h2 id="edit-dialog" tabindex="-1">Edit Dialog <a class="header-anchor" href="#edit-dialog" aria-label="Permalink to &quot;Edit Dialog&quot;">​</a></h2><ol><li>Click <strong>Edit</strong> on a row.</li><li>Top <strong>Alert</strong> (if any): callback URLs, connection examples (<code>GetAlert</code>).</li><li>Form fields from <code>CoreSetting/GetFields</code>:</li></ol><table tabindex="0"><thead><tr><th>Control type <code>type</code></th><th>UI</th></tr></thead><tbody><tr><td>Default</td><td>Single-line <strong>text</strong> (<code>el-input</code>)</td></tr><tr><td><code>checkbox</code></td><td><strong>Switch</strong></td></tr><tr><td><code>file</code></td><td><strong>Choose file</strong> (≤10KB, Base64; can remove selected file)</td></tr></tbody></table><ol start="4"><li><strong>Confirm</strong> calls <code>CoreSetting/update</code>, closes dialog, refreshes list.</li></ol>',4)),o(a,{src:"/cms/settings/settings-integrations-edit-dialog.png",alt:"Edit integration dialog",width:"1120"}),t[3]||(t[3]=e('<div class="info custom-block"><p class="custom-block-title">CMS vs API</p><ul><li><strong>This doc (CMS)</strong>: which group, where to click, field types, save flow.</li><li><strong>API docs</strong>: script calls, callbacks, <code>k.payment.*</code>, etc. Payment field details live in <a href="/kb-docs/api/payment/">k.payment</a> sub-pages—not duplicated in CMS with secrets.</li></ul></div><h2 id="groups-and-docs" tabindex="-1">Groups and Docs <a class="header-anchor" href="#groups-and-docs" aria-label="Permalink to &quot;Groups and Docs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Doc</th><th>Typical items</th></tr></thead><tbody><tr><td><strong>Database</strong></td><td><a href="./database.html">Database</a></td><td>Mysql, SqlServer, Mongo, Redis, Sqlite</td></tr><tr><td><strong>Payment</strong></td><td><a href="./payment.html">Payment</a></td><td>Alipay, WeChatV3, Stripe, Paypal…</td></tr><tr><td><strong>SMS</strong></td><td><a href="./sms.html">SMS</a></td><td>AliSMS, TencentSMSSetting, ChinaMobileSMSSetting</td></tr><tr><td><strong>OAuth2</strong></td><td><a href="./oauth2.html">OAuth2</a></td><td>Google, Facebook, WeChat/Weibo/Apple login</td></tr><tr><td><strong>Storage</strong></td><td><a href="./storage.html">Storage</a></td><td>AmazonS3, AliyunOSS, AzureBlob</td></tr><tr><td><strong>Others</strong></td><td><a href="./others.html">Others</a></td><td>JwtSetting, FirebaseSetting</td></tr></tbody></table><p>Visible items vary by Kooboo version and installed modules; list after login is authoritative.</p><h2 id="relationship-to-other-menus" tabindex="-1">Relationship to Other Menus <a class="header-anchor" href="#relationship-to-other-menus" aria-label="Permalink to &quot;Relationship to Other Menus&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Integration</th><th>Menus after config</th></tr></thead><tbody><tr><td>Database · Mysql / SqlServer</td><td><a href="./../../database/mysql-table.html">MySQL tables</a>, <a href="./../../database/sqlserver-table.html">SQL Server tables</a></td></tr><tr><td>Payment</td><td><a href="./../../commerce/">Commerce</a>, <a href="/kb-docs/api/payment/">k.payment</a> in Code</td></tr><tr><td>OAuth2</td><td>Front-end login callbacks; dev: <a href="./../../development/authentication.html">Authentication</a> (JWT gateway rules)</td></tr><tr><td>Storage</td><td><a href="./../../site/media.html">Media library</a>, content files</td></tr><tr><td>JwtSetting</td><td>JWT validation in <a href="./../../development/authentication.html">Authentication</a> rules</td></tr></tbody></table><p>Commerce <strong>Settings</strong> does not duplicate Payment—configure <strong>Payment</strong> group here.</p><h2 id="typical-workflow" tabindex="-1">Typical Workflow <a class="header-anchor" href="#typical-workflow" aria-label="Permalink to &quot;Typical Workflow&quot;">​</a></h2><ol><li>Expand the <strong>Group</strong>, find the item.</li><li><strong>Edit</strong>, fill vendor parameters per Alert, <strong>save</strong>.</li><li>Verify in business menus (MySQL tables after Mysql, test payment after Alipay, etc.).</li><li>Read matching API docs for scripts.</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Description</th></tr></thead><tbody><tr><td><a href="./../">Settings overview</a></td><td>Full settings menu</td></tr><tr><td><a href="/kb-docs/api/payment/">k.payment</a></td><td>Payment API</td></tr><tr><td><a href="/kb-docs/api/database/">k.DB</a></td><td>Database API</td></tr></tbody></table>',11))])}const S=n(d,[["render",l]]);export{b as __pageData,S as default};
